        {&ADC4->CR,ADC_CR_ADDIS},{&ADC4->CR,ADC_CR_ADCAL},{&ADC4->IER,ADC_IER_EOCIE},
        {&ADC4->CFGR1,ADC_CFGR1_EXTEN_0},{&ADC4->CFGR1,ADC_CFGR1_CONT},
